#include <bits/stdc++.h>
using namespace std;

const int MODULUS = 998244353;

int gcdValue, xCoefficient, yCoefficient;

void computeGCD(int a, int b) {
    if (b == 0) {
        gcdValue = a; xCoefficient = 1; yCoefficient = 0;
    } else {
        computeGCD(b, a % b);
        int tempX = xCoefficient - a / b * yCoefficient;
        xCoefficient = yCoefficient;
        yCoefficient = tempX;
    }
}

int findInverse(int a) {
    computeGCD(a, MODULUS);
    return xCoefficient < 0 ? xCoefficient + MODULUS : xCoefficient;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int nVal, mVal, kVal;
    cin >> nVal >> mVal >> kVal;
    int invM = findInverse(mVal);
    vector<long long> dpArray(kVal + 1, 0);
    dpArray[0] = 1;

    for (int i = 0; i < kVal; i++) {
        for (int d = kVal - 1; d >= 0; d--) {
            if (dpArray[d] != 0) {
                dpArray[d + 1] = (dpArray[d + 1] + dpArray[d] * (nVal - d)) % MODULUS;
                dpArray[d] = (dpArray[d] * d) % MODULUS;
            }
        }
    }

    long long probability = 1;
    long long result = 0;
    for (int d = 1; d <= kVal; d++) {
        probability = (probability * invM) % MODULUS;
        result = (result + dpArray[d] * probability) % MODULUS;
    }
    cout << result << "\n";
    return 0;
}

